import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:hr_oto_design_system/hr_oto_design_system.dart';
import 'package:http/http.dart' as http;

const apiUrl = String.fromEnvironment('HR_OTO_API_URL', defaultValue: 'http://localhost:8000/api/v1');
final employeeApiProvider = Provider((_) => EmployeeApi(apiUrl));
class EmployeeApi {
  EmployeeApi(this.base); final String base; final storage=const FlutterSecureStorage(); String? token;
  Map<String,String> get headers=>{'Content-Type':'application/json',if(token!=null)'Authorization':'Bearer $token'};
  dynamic decode(http.Response r){final x=r.body.isEmpty?{}:jsonDecode(r.body);if(r.statusCode<200||r.statusCode>=300)throw Exception(x is Map&&x['detail']!=null?x['detail']:'API შეცდომა');return x;}
  Future<void> login(String email,String password,String? mfa)async{final r=await http.post(Uri.parse('$base/auth/login'),headers:headers,body:jsonEncode({'email':email,'password':password,if(mfa!=null&&mfa.isNotEmpty)'mfa_code':mfa}));token=decode(r)['access_token'];await storage.write(key:'employee_token',value:token);}
  Future<Map<String,dynamic>> dashboard(String code)=>_map('/employee/$code/me/dashboard');
  Future<List<Map<String,dynamic>>> list(String code,String path)async=>(decode(await http.get(Uri.parse('$base/employee/$code/me/$path'),headers:headers))as List).cast<Map<String,dynamic>>();
  Future<Map<String,dynamic>> _map(String path)async=>Map<String,dynamic>.from(decode(await http.get(Uri.parse('$base$path'),headers:headers)));
  Future<void> leave(String code,Map<String,dynamic> data)async{decode(await http.post(Uri.parse('$base/employee/$code/me/leave'),headers:headers,body:jsonEncode(data)));}
}

void main()=>runApp(const ProviderScope(child:EmployeeApp()));
class EmployeeApp extends StatefulWidget{const EmployeeApp({super.key});@override State<EmployeeApp> createState()=>_EmployeeAppState();}
class _EmployeeAppState extends State<EmployeeApp>{ThemeMode mode=ThemeMode.system;bool logged=false;String code='';@override Widget build(BuildContext c)=>MaterialApp(title:'HR-OTO Employee',debugShowCheckedModeBanner:false,theme:HrOtoTheme.light(),darkTheme:HrOtoTheme.dark(),themeMode:mode,home:logged?EmployeeWorkspace(code:code,onTheme:()=>setState(()=>mode=mode==ThemeMode.dark?ThemeMode.light:ThemeMode.dark)):EmployeeLogin(onLogged:(x)=>setState((){code=x;logged=true;})));}
class EmployeeLogin extends ConsumerStatefulWidget{const EmployeeLogin({super.key,required this.onLogged});final ValueChanged<String> onLogged;@override ConsumerState<EmployeeLogin> createState()=>_EmployeeLoginState();}
class _EmployeeLoginState extends ConsumerState<EmployeeLogin>{final email=TextEditingController(),password=TextEditingController(),mfa=TextEditingController(),code=TextEditingController();bool busy=false;String? error;@override Widget build(BuildContext c)=>Scaffold(body:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:440),child:Card(child:Padding(padding:const EdgeInsets.all(32),child:Column(mainAxisSize:MainAxisSize.min,children:[const HrOtoLogo(size:94),Text('HR-OTO Employee',style:TextStyle(fontSize:27,fontWeight:FontWeight.w800)),const SizedBox(height:18),TextField(controller:code,decoration:const InputDecoration(labelText:'Company Code')),TextField(controller:email,decoration:const InputDecoration(labelText:'ელფოსტა')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'პაროლი')),TextField(controller:mfa,decoration:const InputDecoration(labelText:'MFA კოდი')),if(error!=null)Text(error!,style:TextStyle(color:Theme.of(c).colorScheme.error)),const SizedBox(height:14),SizedBox(width:double.infinity,child:FilledButton(onPressed:busy?null:_login,child:Text(busy?'...':'შესვლა')))]))))));Future<void> _login()async{setState(()=>busy=true);try{await ref.read(employeeApiProvider).login(email.text,password.text,mfa.text);widget.onLogged(code.text.trim().toUpperCase());}catch(e){setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}}
class EmployeeWorkspace extends StatefulWidget{const EmployeeWorkspace({super.key,required this.code,required this.onTheme});final String code;final VoidCallback onTheme;@override State<EmployeeWorkspace> createState()=>_EmployeeWorkspaceState();}
class _EmployeeWorkspaceState extends State<EmployeeWorkspace>{int index=0;final labels=['მთავარი','გრაფიკი','დასწრება','შვებულება','განცხადებები'];final icons=[Icons.home_outlined,Icons.calendar_month_outlined,Icons.access_time,Icons.beach_access_outlined,Icons.campaign_outlined];@override Widget build(BuildContext c){final wide=MediaQuery.sizeOf(c).width>=760;final pages=[EmployeeDashboard(code:widget.code),SchedulePage(code:widget.code),AttendancePage(code:widget.code),LeavePage(code:widget.code),AnnouncementsPage(code:widget.code)];return Scaffold(appBar:AppBar(title:Text('HR-OTO Employee • ${labels[index]}'),actions:[IconButton(onPressed:widget.onTheme,icon:const Icon(Icons.brightness_6_outlined)),IconButton(onPressed:()=>setState(()=>index=4),icon:const Icon(Icons.notifications_none))]),body:Row(children:[if(wide)NavigationRail(selectedIndex:index,labelType:NavigationRailLabelType.all,onDestinationSelected:(x)=>setState(()=>index=x),destinations:[for(var i=0;i<labels.length;i++)NavigationRailDestination(icon:Icon(icons[i]),label:Text(labels[i]))]),if(wide)const VerticalDivider(width:1),Expanded(child:pages[index])]),bottomNavigationBar:wide?null:NavigationBar(selectedIndex:index,onDestinationSelected:(x)=>setState(()=>index=x),destinations:[for(var i=0;i<labels.length;i++)NavigationDestination(icon:Icon(icons[i]),label:labels[i])]));}}
class EmployeeDashboard extends ConsumerStatefulWidget{const EmployeeDashboard({super.key,required this.code});final String code;@override ConsumerState<EmployeeDashboard> createState()=>_EmployeeDashboardState();}
class _EmployeeDashboardState extends ConsumerState<EmployeeDashboard>{late Future<Map<String,dynamic>> future;@override void initState(){super.initState();future=ref.read(employeeApiProvider).dashboard(widget.code);}@override Widget build(BuildContext c)=>FutureBuilder(future:future,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text(s.error.toString()));final d=s.data!,p=d['profile'];final b=d['leave_balance'];return ListView(padding:const EdgeInsets.all(24),children:[Row(children:[const CircleAvatar(radius:34,child:Icon(Icons.person)),const SizedBox(width:14),Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${p['first_name']} ${p['last_name']}',style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),Text('Employee ID: ${p['employee_id']}')])]),const SizedBox(height:24),Card(child:ListTile(leading:const Icon(Icons.schedule),title:const Text('დღევანდელი გრაფიკი'),subtitle:Text(d['today_schedule']==null?'გრაფიკი არ არის':'${d['today_schedule']['start']} — ${d['today_schedule']['end']}'))),Card(child:ListTile(leading:const Icon(Icons.beach_access),title:const Text('შვებულების ბალანსი'),subtitle:Text('დარჩენილია ${b['remaining_days']} დღე'))),Card(child:ListTile(leading:const Icon(Icons.verified_outlined),title:const Text('დასწრების ვერიფიკაცია'),subtitle:Text(d['today_attendance']?['verified']==true?'დადასტურებული':'მეთოდი ჯერ არ არის არჩეული')))]);});}
class DataPage extends ConsumerStatefulWidget{const DataPage({super.key,required this.code,required this.title,required this.path,required this.icon});final String code,title,path;final IconData icon;@override ConsumerState<DataPage> createState()=>_DataPageState();}
class _DataPageState extends ConsumerState<DataPage>{late Future<List<Map<String,dynamic>>> future;@override void initState(){super.initState();future=ref.read(employeeApiProvider).list(widget.code,widget.path);}@override Widget build(BuildContext c)=>FutureBuilder(future:future,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text(s.error.toString()));final items=s.data!;return ListView(padding:const EdgeInsets.all(24),children:[Text(widget.title,style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:12),if(items.isEmpty)const Text('მონაცემები ჯერ არ არის'),for(final x in items)Card(child:ListTile(leading:Icon(widget.icon),title:Text(x['title']?.toString()??x['date']?.toString()??'ჩანაწერი'),subtitle:Text(x['body']?.toString()??x['status']?.toString()??x['worked_minutes']?.toString()??''))) ]);});}
class SchedulePage extends StatelessWidget{const SchedulePage({super.key,required this.code});final String code;@override Widget build(BuildContext c)=>DataPage(code:code,title:'კვირისა და თვის გრაფიკები',path:'schedules',icon:Icons.calendar_month);}
class AttendancePage extends StatelessWidget{const AttendancePage({super.key,required this.code});final String code;@override Widget build(BuildContext c)=>DataPage(code:code,title:'დასწრება და შესვენებები',path:'attendance',icon:Icons.access_time);}
class AnnouncementsPage extends StatelessWidget{const AnnouncementsPage({super.key,required this.code});final String code;@override Widget build(BuildContext c)=>DataPage(code:code,title:'კომპანიის განცხადებები',path:'announcements',icon:Icons.campaign);}
class LeavePage extends ConsumerWidget{const LeavePage({super.key,required this.code});final String code;@override Widget build(BuildContext c,WidgetRef ref)=>Column(children:[Expanded(child:DataPage(code:code,title:'შვებულება',path:'leave',icon:Icons.beach_access)),Padding(padding:const EdgeInsets.all(16),child:FilledButton.icon(onPressed:()=>showDialog(context:c,builder:(d){final start=TextEditingController(),end=TextEditingController(),reason=TextEditingController();return AlertDialog(title:const Text('შვებულების მოთხოვნა'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:start,decoration:const InputDecoration(labelText:'დაწყება YYYY-MM-DD')),TextField(controller:end,decoration:const InputDecoration(labelText:'დასასრული YYYY-MM-DD')),TextField(controller:reason,decoration:const InputDecoration(labelText:'მიზეზი'))]),actions:[FilledButton(onPressed:()async{await ref.read(employeeApiProvider).leave(code,{'starts_on':start.text,'ends_on':end.text,'reason':reason.text});if(d.mounted)Navigator.pop(d);},child:const Text('გაგზავნა'))]});}),icon:const Icon(Icons.send),label:const Text('შვებულების მოთხოვნა')))]);}
